import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Synapse Project Boundary","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-07-01-project-boundary.md","filePath":"superpowers/specs/2026-07-01-project-boundary.md","lastUpdated":1782853675000}'),r={name:"superpowers/specs/2026-07-01-project-boundary.md"};function n(d,e,c,i,p,l){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="synapse-project-boundary" tabindex="-1">Synapse Project Boundary <a class="header-anchor" href="#synapse-project-boundary" aria-label="Permalink to &quot;Synapse Project Boundary&quot;">​</a></h1><blockquote><p><strong>What Synapse is, what it isn&#39;t, and how downstream projects use it.</strong></p></blockquote><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p><strong>Synapse</strong> = a Rust framework for building <strong>agent primitives and the mechanisms that connect them</strong> (streaming, A2A protocol, WASM package plumbing, transport).</p><p><strong>Synapse explicitly does NOT do</strong>:</p><ul><li>❌ Agent supervision / scheduling / orchestration</li><li>❌ Cluster management / load balancing</li><li>❌ HTTP serving / API gateway concerns</li><li>❌ Persistence / state stores</li><li>❌ CLI / dashboard / user interfaces</li></ul><p>Those concerns are owned by <strong>downstream projects</strong> (today: Prefrontal; tomorrow: anything else).</p><h2 id="layered-architecture" tabindex="-1">Layered architecture <a class="header-anchor" href="#layered-architecture" aria-label="Permalink to &quot;Layered architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  Layer 4 — User-facing apps                                  │</span></span>
<span class="line"><span>│            shadow-mobile, shadow-desktop, shadow-cli         │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  Layer 3 — Runtime / supervisor                              │</span></span>
<span class="line"><span>│            prefrontal  ·  other &quot;supervisor&quot; projects        │</span></span>
<span class="line"><span>│            (loads WASM agents, supervises, A2A-routes)       │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  Layer 2 — Synapse (this project)                            │</span></span>
<span class="line"><span>│            streaming core · A2A SDK wrap · WASM runtime env  │</span></span>
<span class="line"><span>│            transport adapters · component primitives         │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  Layer 1 — Foundation crates                                 │</span></span>
<span class="line"><span>│            wasmtime · a2a-rs · reqwest · wasi-http · axum   │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────────┘</span></span></code></pre></div><p>Layer 2 is Synapse; layers 1 and 3+ are somebody else&#39;s concern.</p><h2 id="what-synapse-provides" tabindex="-1">What Synapse provides <a class="header-anchor" href="#what-synapse-provides" aria-label="Permalink to &quot;What Synapse provides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Owned by Synapse</th><th>Notes</th></tr></thead><tbody><tr><td><strong><code>stream</code></strong> (<code>src/stream/</code>)</td><td>✅</td><td><code>StreamReader&lt;T&gt;</code>, <code>StreamWriter&lt;T&gt;</code>, <code>CancelHandle</code>, generic over <code>T</code></td></tr><tr><td><strong><code>adk::stream</code></strong></td><td>✅</td><td><code>AgentStreamEvent</code>, <code>AgentStream</code> (the unified event bus)</td></tr><tr><td><strong><code>components::model::delta</code></strong></td><td>✅</td><td><code>MessageDelta</code>, <code>FinishReason</code>, <code>Usage</code></td></tr><tr><td><strong><code>components::model::*</code></strong></td><td>✅</td><td><code>BaseChatModel</code> trait + concrete (OpenAI / Anthropic) impls</td></tr><tr><td><strong><code>adk::agent</code></strong></td><td>✅</td><td><code>Agent</code> trait, <code>ChatModelAgent</code>, <code>GraphReActAgent</code></td></tr><tr><td><strong><code>adk::multiagent</code></strong></td><td>⚠️</td><td><strong>In-scope as reference patterns</strong>; Prefrontal-style supervisors replace these</td></tr><tr><td><strong><code>transport</code></strong></td><td>✅</td><td><code>HttpClient</code> trait + <code>ReqwestHttpClient</code> / <code>WasiHttpClient</code></td></tr><tr><td><strong><code>transport::sse</code></strong></td><td>✅</td><td>SSE parser + <code>HttpClientSse::sse_post</code> (native impl)</td></tr><tr><td><strong><code>wasm</code></strong> (<code>src/wasm/</code>)</td><td>✅</td><td><code>WasmPackage</code>, <code>WasmRuntime</code>, <code>AgentInstance</code>, registry, manager — reusable infrastructure</td></tr><tr><td><strong><code>a2a</code></strong></td><td>✅</td><td>Thin wrappers over <code>a2a-rs</code> SDK; protocol-only, no hosting concerns</td></tr></tbody></table><h2 id="what-synapse-does-not-provide-deliberately" tabindex="-1">What Synapse does NOT provide (deliberately) <a class="header-anchor" href="#what-synapse-does-not-provide-deliberately" aria-label="Permalink to &quot;What Synapse does NOT provide (deliberately)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>Why it&#39;s not in Synapse</th><th>Where it lives</th></tr></thead><tbody><tr><td>Host an axum server</td><td>Prefrontal&#39;s job</td><td><code>prefrontal/</code></td></tr><tr><td>Spawn / supervise WASM instances</td><td>&quot;</td><td><code>prefrontal/src/supervisor.rs</code></td></tr><tr><td>Persist task state across restarts</td><td>Storage choice is deployment-specific</td><td><code>prefrontal/src/persistence/</code></td></tr><tr><td>Schedule agents across machines</td><td>Cluster concern</td><td>A future <code>prefrontal-cluster/</code> or sibling project</td></tr><tr><td>UI / CLI / dashboard</td><td>App concern</td><td><code>shadow-*</code> projects</td></tr><tr><td>Auth / multi-tenancy</td><td>Deployment concern</td><td>Layer 4 or Reverse proxy</td></tr><tr><td>LLM provider secrets at rest</td><td>Secrets handling is host concern</td><td>Prefrontal or operator</td></tr></tbody></table><h2 id="what-an-agent-looks-like-to-a-downstream-project" tabindex="-1">What an &quot;Agent&quot; looks like to a downstream project <a class="header-anchor" href="#what-an-agent-looks-like-to-a-downstream-project" aria-label="Permalink to &quot;What an &quot;Agent&quot; looks like to a downstream project&quot;">​</a></h2><p>The minimum a downstream project (Prefrontal) needs to do to host a Synapse agent:</p><ol><li><strong>Compile the agent crate to wasm32-wasip2</strong> — see <code>docs/wasm-compilation-guide.md</code> for the step-by-step.</li><li><strong>Load it</strong> via <code>synapse::wasm::WasmRuntime::load(package)</code>.</li><li><strong>Bind an A2A route</strong> to it via <code>synapse::a2a::server::*</code> (the thin wrapper around <code>a2a-rs</code>).</li><li><strong>Forward outbound A2A calls</strong> through <code>synapse::a2a::client::*</code>.</li></ol><p>The downstream project owns the URL paths, the WebSocket upgrades, the auth middleware, the task store — Synapse does not.</p><h2 id="reusable-contract-for-downstream-projects" tabindex="-1">Reusable contract for downstream projects <a class="header-anchor" href="#reusable-contract-for-downstream-projects" aria-label="Permalink to &quot;Reusable contract for downstream projects&quot;">​</a></h2><p>Two things must stay stable across versions, because multiple downstream projects depend on them:</p><ol><li><p><strong>WASM Agent ABI</strong> — the function signatures a Synapse-compiled agent WASM exposes. See <code>docs/wasm-agent-abi.md</code>. <strong>Breaking changes here require a major version bump.</strong></p></li><li><p><strong>A2A wire compatibility</strong> — guaranteed by delegating to upstream <code>a2a-rs</code> v0.4.x. Pin tightly; track upstream minor bumps quarterly.</p></li></ol><p>Everything else (internal trait design, helper modules) can change freely across minor versions.</p><h2 id="on-providing-an-agent-template" tabindex="-1">On providing an &quot;Agent template&quot; <a class="header-anchor" href="#on-providing-an-agent-template" aria-label="Permalink to &quot;On providing an &quot;Agent template&quot;&quot;">​</a></h2><p>Two options were considered:</p><table tabindex="0"><thead><tr><th>Option</th><th>Pros</th><th>Cons</th></tr></thead><tbody><tr><td><strong>(A) Template repo</strong> (<code>synapse-agent-template</code>)</td><td>Easy to copy; clear example</td><td>Duplicate; drifts from Synapse</td></tr><tr><td><strong>(B) <code>synapse new</code> CLI / <code>synapse-sdk</code> sub-crate</strong></td><td>Stays current; blessed path</td><td>Requires maintaining a tool</td></tr></tbody></table><p><strong>Decision (proposed)</strong>: ship <strong>(B)</strong> as a thin <code>cargo-generate</code>-style template under <code>templates/agent/</code> in this repo (read-only skeleton the user copies); skip the CLI for v1. The template pulls the agent into a workspace with <code>Cargo.toml</code> already configured for <code>wasm32-wasip2</code> + the WASM Agent ABI exports documented in <code>docs/wasm-agent-abi.md</code>.</p><p>The <strong>agent template</strong> is the user-facing &quot;hello world&quot; of building a Synapse agent. It compiles to one WASM file Prefrontal (or any other layer-3 host) can load.</p><h2 id="on-the-docs-split" tabindex="-1">On the docs split <a class="header-anchor" href="#on-the-docs-split" aria-label="Permalink to &quot;On the docs split&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>Owner</th></tr></thead><tbody><tr><td><code>docs/howto/*.md</code> — how to call each component</td><td><strong>Synapse</strong></td></tr><tr><td><code>docs/reference/*.md</code> — API reference</td><td><strong>Synapse</strong></td></tr><tr><td><code>docs/wasm-agent-abi.md</code> — WASM exports</td><td><strong>Synapse</strong></td></tr><tr><td><code>docs/wasm-compilation-guide.md</code> — <code>cargo build --target wasm32-wasip2</code></td><td><strong>Synapse</strong></td></tr><tr><td>&quot;How Prefrontal uses Synapse&quot; / &quot;Architecture&quot;</td><td><strong>Prefrontal</strong> (their docs)</td></tr><tr><td>&quot;How shadow-mobile embeds Prefrontal&quot;</td><td><strong>shadow-mobile</strong> (their docs)</td></tr></tbody></table><p>This keeps Synapse documentation strictly about <em>how to use the API</em>, not about <em>what the deployment topology looks like</em>.</p><h2 id="future-proofing" tabindex="-1">Future-proofing <a class="header-anchor" href="#future-proofing" aria-label="Permalink to &quot;Future-proofing&quot;">​</a></h2><p>Other projects in the family (any sibling &quot;supervisor&quot; or &quot;host&quot; project — call them <strong>layer-3 projects</strong>) should all be able to:</p><ul><li>Include <code>synapse</code> as a Cargo dependency</li><li>Use <code>synapse::wasm::WasmRuntime</code> to load any Synapse-compiled agent</li><li>Use <code>synapse::a2a::*</code> to wire up A2A protocol handling</li><li>Use <code>synapse::stream::*</code> to consume agent event streams</li></ul><p>Synapse will track this via:</p><ul><li><strong>Sematic Versioning</strong>: pre-1.0, expect minor versions to break the WASM ABI; we&#39;ll bump major (e.g. 0.2.x → 1.0) the moment we commit to stable ABI.</li><li><strong>Crate features</strong>: optional sub-modules (e.g. <code>embeddings</code>, <code>rag</code>, <code>mcp</code>) so downstream projects only compile what they use.</li><li><strong>Doc-test coverage</strong>: every public API in <code>docs/reference/</code> should have a runnable example as a <code>///</code> docstring.</li></ul>`,35)])])}const u=t(r,[["render",n]]);export{g as __pageData,u as default};
